const messages = items;
if (messages.length === 0 || !messages[0]?.json?.group_id) return [];

const grouped = {};
messages.forEach(item => {
  const data = item.json;
  const key = data.group_id;
  if (!grouped[key]) {
    grouped[key] = {
      group_id: data.group_id,
      group_name: data.group_name || "Grupo Sem Nome",
      ids: [],
      conversa: ""
    };
  }
  grouped[key].ids.push(data.id);
  grouped[key].conversa += `[${data.sender_name || 'Desconhecido'} - Tel: ${data.sender_phone}]: ${data.message_text}\n`;
});

return Object.values(grouped).map(group => ({ 
  json: { 
    group_id: group.group_id, 
    group_name: group.group_name, 
    raw_ids: group.ids, 
    conversa_acumulada: group.conversa 
  } 
}));

