const iaResponse = JSON.parse(items[0]?.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}');
const rawIds = $('JS Group Messages').first().json.raw_ids || [];
const groupName = $('JS Group Messages').first().json.group_name || "Desconhecido";
const posto = iaResponse.posto || groupName;

const insertsOcorrencias = [];

if (iaResponse.status === "sucesso" && Array.isArray(iaResponse.ocorrencias)) {
  iaResponse.ocorrencias.forEach(o => {
    insertsOcorrencias.push({
      posto_afetado: posto,
      categoria: o.categoria,
      gravidade: o.gravidade,
      descricao_fato: `[Envolvido: ${o.colaborador_envolvido}] - ${o.resumo_operacional}`,
      trecho_original: o.trecho_original,
      resolvido: false
    });
  });
}

return [{
  json: {
    inserts: insertsOcorrencias,
    ids_to_update: rawIds,
    has_inserts: insertsOcorrencias.length > 0
  }
}];
